def get_inference_settings() -> dict[str, str | int]:
    with _connect() as conn:
        rows = conn.execute(
            "SELECT key, value FROM app_settings WHERE key IN (?, ?)",
            (_LITERT_BACKEND_KEY, _CHAT_MAX_NUM_TOKENS_KEY),
        ).fetchall()
    saved = dict(rows)
    backend_val = saved.get(_LITERT_BACKEND_KEY) or settings.litert_backend
    tokens_val = saved.get(_CHAT_MAX_NUM_TOKENS_KEY)
    try:
        max_num_token = int(tokens_val) if tokens_val is not None else settings.chat_max_num_tokens
    except (ValueError, TypeError):
        max_num_token = settings.chat_max_num_tokens
    return {
        "litert_backend": backend_val,
        "max_num_token": max_num_token,
    }

def normalize_tool_arguments(raw_args: str) -> str:
    """Normalizes raw tool arguments (strict JSON, relaxed JSON, Gemma 4 tokens, or Python dict) to a valid JSON string."""
    args_str = raw_args.strip()
    if not args_str:
        return "{}"

    # Replace Gemma 4 special quote tokens
    args_str = args_str.replace('<|"|>', '"').replace("<|'|>", "'")

    # Standardize wrapping braces
    if args_str.startswith("(") and args_str.endswith(")"):
        args_str = "{" + args_str[1:-1] + "}"
    elif not args_str.startswith("{"):
        args_str = "{" + args_str + "}"

    # 1. Direct JSON parse
    try:
        parsed = json.loads(args_str)
        if isinstance(parsed, dict):
            return json.dumps(parsed)
    except Exception:
        pass

    # 2. Relaxed JSON: quote unquoted dictionary keys
    relaxed = _UNQUOTED_KEY_RE.sub(r'\1"\2":', args_str)
    relaxed = re.sub(r"\bTrue\b", "true", relaxed)
    relaxed = re.sub(r"\bFalse\b", "false", relaxed)
    relaxed = re.sub(r"\bNone\b", "null", relaxed)

    try:
        parsed = json.loads(relaxed)
        if isinstance(parsed, dict):
            return json.dumps(parsed)
    except Exception:
        pass

    # 3. Handle Python dict syntax via ast.literal_eval
    try:
        evaluated = ast.literal_eval(args_str)
        if isinstance(evaluated, dict):
            return json.dumps(evaluated)
    except Exception:
        pass

    # 4. Fallback: single-to-double quote substitution on relaxed string
    try:
        sq_replaced = re.sub(r"(?<!\\)'", '"', relaxed)
        parsed = json.loads(sq_replaced)
        if isinstance(parsed, dict):
            return json.dumps(parsed)
    except Exception:
        pass

    return args_str

def _parse_single_tool_call_body(body: str) -> ToolCall | None:
    """Parses inner content of a <tool_call> block into a ToolCall, supporting Gemma and JSON formats."""
    body_clean = body.strip()
    if not body_clean:
        return None

    call_id = f"call_{uuid.uuid4().hex[:12]}"

    # Format 1: Gemma 4 format (call:func_name{...})
    gemma_match = _GEMMA_CALL_RE.match(body_clean)
    if gemma_match:
        func_name = gemma_match.group(1).strip()
        raw_args = gemma_match.group(2).strip()
        norm_args = normalize_tool_arguments(raw_args)
        return ToolCall(
            id=call_id,
            type="function",
            function=FunctionCall(name=func_name, arguments=norm_args),
        )

    # Format 2: DeepSeek / Standard JSON format ({"name": "...", "arguments": ...})
    try:
        data = json.loads(body_clean)
        if isinstance(data, dict):
            if "name" in data:
                func_name = str(data["name"])
                raw_args = data.get("arguments", {})
                norm_args = (
                    json.dumps(raw_args)
                    if isinstance(raw_args, (dict, list))
                    else str(raw_args)
                )
                return ToolCall(
                    id=call_id,
                    type="function",
                    function=FunctionCall(name=func_name, arguments=norm_args),
                )
            if "function" in data and isinstance(data["function"], dict):
                fn_data = data["function"]
                func_name = str(fn_data.get("name", ""))
                raw_args = fn_data.get("arguments", {})
                norm_args = (
                    json.dumps(raw_args)
                    if isinstance(raw_args, (dict, list))
                    else str(raw_args)
                )
                return ToolCall(
                    id=call_id,
                    type="function",
                    function=FunctionCall(name=func_name, arguments=norm_args),
                )
    except Exception:
        pass

    # Format 3: Relaxed JSON with unquoted keys in DeepSeek format
    try:
        norm_body = normalize_tool_arguments(body_clean)
        data = json.loads(norm_body)
        if isinstance(data, dict) and "name" in data:
            func_name = str(data["name"])
            raw_args = data.get("arguments", {})
            norm_args = (
                json.dumps(raw_args)
                if isinstance(raw_args, (dict, list))
                else str(raw_args)
            )
            return ToolCall(
                id=call_id,
                type="function",
                function=FunctionCall(name=func_name, arguments=norm_args),
            )
    except Exception:
        pass

    return None

async def openai_compatible_exception_handler(request: Request, exc: HTTPException) -> JSONResponse:
    if request.url.path.startswith("/v1/") and isinstance(exc.detail, dict) and "error" in exc.detail:
        return JSONResponse(status_code=exc.status_code, content=exc.detail)
    if request.url.path.startswith("/v1/"):
        return JSONResponse(
            status_code=exc.status_code,
            content={"error": {"message": str(exc.detail), "type": "invalid_request_error", "param": None, "code": None}},
        )
    return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})

async def openai_compatible_validation_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    if not request.url.path.startswith("/v1/"):
        return JSONResponse(
            status_code=422, content={"detail": jsonable_encoder(exc.errors())}
        )
    first_error = exc.errors()[0] if exc.errors() else {}
    param = ".".join(str(p) for p in first_error.get("loc", []) if p != "body")
    return JSONResponse(
        status_code=422,
        content={
            "error": {
                "message": first_error.get("msg", "Invalid request."),
                "type": "invalid_request_error",
                "param": param or None,
                "code": None,
            }
        },
    )

async def sandbox_read_file(
    session_id: str,
    path: str,
) -> dict[str, Any]:
    """Read a file from the sandbox workspace."""
    try:
        content = await sandbox_service.read_session_file(session_id=session_id, path=path)
        return {"status": "success", "session_id": session_id, "path": path, "content": content}
    except Exception as exc:
        logger.warning("Error in sandbox_read_file: %s", exc)
        return {"status": "error", "error": str(exc), "path": path}

async def sandbox_write_file(
    session_id: str,
    path: str,
    content: str,
    is_base64: bool = False,
) -> dict[str, Any]:
    """Write a file into the sandbox workspace."""
    try:
        await sandbox_service.write_session_file(
            session_id=session_id,
            path=path,
            content=content,
            is_base64=is_base64,
        )
        return {"status": "success", "session_id": session_id, "path": path}
    except Exception as exc:
        logger.warning("Error in sandbox_write_file: %s", exc)
        return {"status": "error", "error": str(exc), "path": path}

async def search_web(
    query: str,
    max_results: int = 5,
    categories: list[str] | None = None,
    language: str = "auto",
) -> list[dict[str, Any]]:
    """Execute a web search and return structured summary items (title, url, snippet)."""
    try:
        response = await searxng_service.search(
            query=query,
            max_results=max_results,
            categories=categories,
            language=language,
        )
        return [
            {
                "title": r.title,
                "url": r.url,
                "snippet": r.snippet,
                "published_date": r.published_date,
                "engine": r.engine,
            }
            for r in response.results
        ]
    except Exception as exc:
        logger.warning("Error executing search_web tool: %s", exc)
        return [
            {
                "error": f"Search execution failed: {exc}",
                "query": query,
            }
        ]

