def validate_crawl_url(url: str, allow_private: bool = False) -> str:
    """
    Validate that the URL has an HTTP/HTTPS scheme and does not target
    private, loopback, or cloud-metadata IP addresses (SSRF prevention).
    """
    cleaned = url.strip()
    if not cleaned:
        raise ValueError("URL cannot be empty.")

    parsed = urlparse(cleaned)
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Invalid URL scheme '{parsed.scheme}'. Only http and https are permitted.")

    hostname = parsed.hostname
    if not hostname:
        raise ValueError("URL must include a valid hostname.")

    if not allow_private:
        # Check direct localhost string
        if hostname.lower() in ("localhost", "127.0.0.1", "::1", "0.0.0.0"):
            raise ValueError(f"Requests to local address '{hostname}' are blocked for security.")

        # Check if hostname is an IP address
        try:
            ip = ipaddress.ip_address(hostname)
            is_ip = True
        except ValueError:
            is_ip = False

        if is_ip and (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved):
            raise ValueError(f"Requests to private/internal IP '{hostname}' are blocked for security.")


    return cleaned

def parse_plan_text(text: str) -> list[PlanStep]:
    steps: list[PlanStep] = []
    lines = text.strip().splitlines()
    for line in lines:
        cleaned = line.strip()
        # Match "1. Step description" or "- [ ] Step description"
        match = re.match(r"^(\d+\.|\-|\*)\s+(.*)", cleaned)
        if match:
            desc = match.group(2).strip()
            if desc:
                steps.append(PlanStep(title=desc, status="pending"))
    if not steps and text.strip():
        # Fallback to single step if no numbered items matched
        steps.append(PlanStep(title=text.strip()[:100], status="pending"))
    return steps

def parse_review_verdict(text: str) -> str:
    match = re.search(r"VERDICT:\s*(pass|retry|continue)", text, re.IGNORECASE)
    if match:
        return match.group(1).lower()
    # Default to pass if positive or stop indicators, otherwise pass if final output ready
    if "pass" in text.lower():
        return "pass"
    return "pass"

async def analyze_node(state: AgentState, emitter: AgentEventEmitter | None = None) -> dict[str, Any]:
    if emitter:
        await emitter.emit_node_start("analyze")

    model_id = state.get("model", settings.agent_default_model) if "model" in state else settings.agent_default_model
    messages = build_analyze_messages(state.get("messages", []))

    text, _ = await generate_with_streaming(messages, model_id, "analyze", emitter)

    step = state.get("step", 0) + 1
    if emitter:
        await emitter.emit_node_end("analyze", {"analysis": text[:100]})

    return {
        "step": step,
        "status": "running",
    }

def compute_action_hash(tool_name: str, args: dict | str) -> str:
    raw = json.dumps(args, sort_keys=True) if isinstance(args, dict) else str(args)
    return hashlib.sha256(f"{tool_name}:{raw}".encode()).hexdigest()[:16]

def is_repeated_action(recent_actions: list[str] | None, threshold: int = 3) -> bool:
    if not recent_actions or len(recent_actions) < threshold:
        return False
    last_action = recent_actions[-1]
    return recent_actions[-threshold:] == [last_action] * threshold

def route_after_act(state: AgentState) -> Literal["observe", "review", "end"]:
    if state.get("status") in ("failed", "cancelled"):
        return "end"

    pending_calls = state.get("pending_tool_calls")
    if not pending_calls:
        return "review"

    recent = state.get("recent_actions") or []
    if is_repeated_action(recent, threshold=3):
        # Prevent infinite repetitive tool call loops
        return "review"

    return "observe"

def route_after_analyze(state: AgentState) -> Literal["plan", "end"]:
    if state.get("status") in ("failed", "cancelled"):
        return "end"
    return "plan"

def route_after_observe(state: AgentState) -> Literal["review", "end"]:
    if state.get("status") in ("failed", "cancelled"):
        return "end"
    return "review"

def route_after_review(state: AgentState) -> Literal["plan", "act", "end"]:
    step = state.get("step", 0)
    max_steps = state.get("max_steps", 15)

    if step >= max_steps:
        return "end"

    if state.get("status") in ("failed", "cancelled", "completed"):
        return "end"

    verdict = state.get("verdict")
    if verdict == "pass":
        return "end"
    elif verdict == "retry":
        return "plan"
    elif verdict == "continue":
        return "act"

    # Default fallback
    return "end"

def append_list(current: list[Any] | None, new: list[Any] | None) -> list[Any]:
    curr = current or []
    if not new:
        return curr
    return curr + new

def _truncate_output(text: str, cap: int | None = None) -> Tuple[str, bool]:
    limit = cap if cap is not None else settings.agent_tool_output_cap
    if len(text) > limit:
        truncated = text[:limit] + f"\n... [TRUNCATED - {len(text) - limit} characters omitted]"
        return truncated, True
    return text, False

def _content_to_text(content: str | list | None) -> str:
    """Flattens a ChatMessage.content to plain text (history replay, token counting)."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    return "".join(part.text for part in content if part.type == "text")

def _decode_image_url(url: str) -> bytes:
    match = _DATA_URL_RE.match(url)
    if not match:
        raise InferenceError(
            "Image attachments must be base64 data URLs (data:<mime>;base64,<data>)."
        )
    try:
        return base64.b64decode(match.group(1), validate=True)
    except binascii.Error as exc:
        raise InferenceError(f"Invalid base64 image data: {exc}") from exc

def _content_to_engine_message(content: str | list | None) -> str | Contents:
    """Converts a ChatMessage.content into what Conversation.send_message expects."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    parts: list = []
    for part in content:
        if part.type == "text":
            parts.append(Content.Text(part.text))
        elif part.type == "image_url":
            parts.append(Content.ImageBytes(_decode_image_url(part.image_url.url)))
    return Contents.of(*parts) if parts else Contents.empty()

def _extract_reasoning(response: Mapping) -> str:
    reasoning_content = response.get("reasoning_content")
    if isinstance(reasoning_content, str) and reasoning_content:
        return reasoning_content
    channels = response.get("channels")
    if isinstance(channels, dict):
        for key in ("thought", "thinking", "reasoning"):
            value = channels.get(key)
            if isinstance(value, str) and value:
                return value
    parts = response.get("content", [])
    if isinstance(parts, list):
        return "".join(
            part.get("text", "")
            for part in parts
            if isinstance(part, dict) and part.get("type") in ("thinking", "reasoning")
        )
    return ""

def _extract_text(response: Mapping) -> str:
    parts = response.get("content", [])
    if isinstance(parts, str):
        return parts
    if not isinstance(parts, list):
        return ""
    return "".join(
        part.get("text", "")
        for part in parts
        if isinstance(part, dict) and part.get("type") == "text"
    )

def _format_tools_declaration(tools: list[ToolDefinition]) -> str:
    """Formats tools definitions into system instructions following Gemma 4 prompt format."""
    declarations = []
    for t in tools:
        fn = t.function
        decl_dict: dict[str, Any] = {}
        if fn.description:
            decl_dict["description"] = fn.description
        if fn.parameters is not None:
            decl_dict["parameters"] = fn.parameters
        decl_json = json.dumps(decl_dict, separators=(",", ":"))
        declarations.append(f"declaration:{fn.name}{decl_json}")
    return "\n".join(declarations)

def _message_to_engine_content(m: ChatMessage) -> str:
    """Formats a message for historical turn replay."""
    base_text = _content_to_text(m.content)
    if m.role == "assistant" and m.tool_calls:
        tool_call_strs = [
            f"<|tool_call>call:{tc.function.name}{tc.function.arguments}<tool_call|>"
            for tc in m.tool_calls
        ]
        calls_text = "\n".join(tool_call_strs)
        return f"{base_text}\n{calls_text}".strip() if base_text else calls_text
    if m.role == "tool":
        return f"<|tool_response>{base_text}<tool_response|>"
    return base_text

def _message_to_engine_input(m: ChatMessage) -> str | Contents:
    """Converts the final message of a conversation to what send_message expects."""
    if m.role == "tool":
        return f"<|tool_response>{_content_to_text(m.content)}<tool_response|>"
    if m.role == "assistant" and m.tool_calls:
        base = _content_to_text(m.content)
        calls = "\n".join(
            f"<|tool_call>call:{tc.function.name}{tc.function.arguments}<tool_call|>"
            for tc in m.tool_calls
        )
        return f"{base}\n{calls}".strip() if base else calls
    return _content_to_engine_message(m.content)

def _next_or_sentinel(it):
    # StopIteration can't cross a thread-pool Future boundary (PEP 479):
    # asyncio.to_thread(next, it) turns it into an opaque RuntimeError
    # ("StopIteration ... cannot be raised into a Future"). Catch it here,
    # inside the worker thread, and signal exhaustion with a sentinel instead.
    try:
        return next(it)
    except StopIteration:
        return _STREAM_DONE

def _row_to_event(row: tuple, columns: list[str]) -> dict[str, Any]:
    event = dict(zip(columns, row))
    if isinstance(event.get("ts"), datetime):
        event["ts"] = event["ts"].isoformat() + "Z"
    if "metadata" in event and event["metadata"]:
        try:
            event["metadata"] = json.loads(event["metadata"])
        except (TypeError, json.JSONDecodeError):
            event["metadata"] = {}
    return event

def _clean_text(raw: str) -> str:
    if not raw:
        return ""
    # Strip HTML tags and unescape entities
    text = _TAG_RE.sub("", raw)
    text = html.unescape(text)
    return " ".join(text.split())

def apply_glob_filters(
    url: str, include_patterns: list[str], exclude_patterns: list[str]
) -> bool:
    parsed = urlparse(url)
    path = parsed.path

    if exclude_patterns:
        for pat in exclude_patterns:
            if fnmatch.fnmatch(path, pat) or fnmatch.fnmatch(url, pat):
                return False

    if include_patterns:
        matched = False
        for pat in include_patterns:
            if fnmatch.fnmatch(path, pat) or fnmatch.fnmatch(url, pat):
                matched = True
                break
        return matched

    return True

async def fetch_robots_txt(
    client: httpx.AsyncClient, root_url: str
) -> tuple[RobotFileParser, list[str]]:
    parsed = urlparse(root_url)
    robots_url = f"{parsed.scheme}://{parsed.netloc}/robots.txt"

    rp = RobotFileParser()
    sitemaps: list[str] = []

    try:
        res = await client.get(robots_url, timeout=10.0)
        if res.is_success and res.text:
            lines = res.text.splitlines()
            rp.parse(lines)
            for line in lines:
                if line.lower().startswith("sitemap:"):
                    parts = line.split(":", 1)
                    if len(parts) == 2 and parts[1].strip():
                        sitemaps.append(parts[1].strip())
    except Exception as exc:
        logger.info("Could not fetch robots.txt for %s: %s", root_url, exc)

    return rp, sitemaps

def normalize_url(url: str) -> str:
    parsed = urlparse(url.strip())
    scheme = parsed.scheme.lower()
    netloc = parsed.netloc.lower()

    # Drop tracking query params
    filtered_qs = []
    if parsed.query:
        for k, v in parse_qsl(parsed.query, keep_blank_values=True):
            if k.lower() not in TRACKING_QUERY_PARAMS:
                filtered_qs.append((k, v))
    new_query = urlencode(filtered_qs)

    path = parsed.path or "/"
    if path != "/" and path.endswith("/"):
        path = path.rstrip("/")

    return urlunparse((scheme, netloc, path, "", new_query, ""))

async def fetch_and_parse_sitemap(
    client: httpx.AsyncClient,
    sitemap_url: str,
    target_host: str,
    depth: int = 1,
    max_depth: int = 3,
) -> list[str]:
    if depth > max_depth:
        return []

    try:
        res = await client.get(sitemap_url, timeout=15.0)
        if not res.is_success or not res.content:
            return []

        content_bytes = res.content
        if sitemap_url.endswith(".gz") or res.headers.get("content-type") == "application/x-gzip":
            try:
                content_bytes = gzip.decompress(content_bytes)
            except Exception as gz_err:
                logger.warning("Gzip decompress failed on %s: %s", sitemap_url, gz_err)
                return []

        # Cap XML size
        if len(content_bytes) > 50 * 1024 * 1024:
            logger.warning("Sitemap XML exceeds 50MB cap on %s", sitemap_url)
            return []

        root = ET.fromstring(content_bytes)
        urls: list[str] = []

        # Check if sitemap index
        # Strip XML namespaces
        tag = root.tag.split("}")[-1] if "}" in root.tag else root.tag

        if tag == "sitemapindex":
            child_sitemaps = []
            for sm in root:
                for elem in sm:
                    elem_tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
                    if elem_tag == "loc" and elem.text:
                        child_sitemaps.append(elem.text.strip())

            for child in child_sitemaps:
                child_urls = await fetch_and_parse_sitemap(
                    client, child, target_host, depth=depth + 1, max_depth=max_depth
                )
                urls.extend(child_urls)
        else:
            # Regular urlset
            for url_elem in root:
                for elem in url_elem:
                    elem_tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
                    if elem_tag == "loc" and elem.text:
                        loc = elem.text.strip()
                        p = urlparse(loc)
                        if p.netloc.lower() == target_host:
                            urls.append(normalize_url(loc))

        return urls

    except Exception as exc:
        logger.warning("Failed to parse sitemap %s: %s", sitemap_url, exc)
        return []

def _coerce_numbers(val: Any) -> Any:
    """Lenient coercion of strings like '$1,299' or '45%' to numbers."""
    if isinstance(val, (int, float)):
        return val
    if isinstance(val, str):
        cleaned = re.sub(r"[^\d.-]", "", val)
        if cleaned:
            try:
                if "." in cleaned:
                    return float(cleaned)
                return int(cleaned)
            except ValueError:
                pass
    return val

