async function backendFetch(path: string, init?: RequestInit): Promise<Response> {
  try {
    return await fetch(`${BACKEND_URL}${path}`, init);
  } catch (error) {
    throw new BackendUnreachableError(error);
  }
}

async function GET() {
  try {
    const backendRes = await backendFetch("/api/models/download/progress");

    if (!backendRes.body) {
      throw new Error("Backend returned an empty progress stream");
    }

    return new Response(backendRes.body, {
      status: backendRes.status,
      headers: {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache, no-transform",
        Connection: "keep-alive",
      },
    });
  } catch (error) {
    console.error("[backend proxy] GET /api/models/download/progress failed:", error);
    return Response.json(
      { error: "Could not reach the backend service. Is it running?" },
      { status: 502 }
    );
  }
}

async function proxyBackendJson(path: string, init?: RequestInit): Promise<Response> {
  try {
    const backendRes = await backendFetch(path, init);
    const body = await backendRes.text();
    return new Response(body, {
      status: backendRes.status,
      headers: { "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error(`[backend proxy] ${init?.method ?? "GET"} ${path} failed:`, error);
    return Response.json(
      { error: "Could not reach the backend service. Is it running?" },
      { status: 502 }
    );
  }
}

