function filterUrlsByGlob(
  urls: string[],
  includePatterns: string[],
  excludePatterns: string[]
): string[] {
  return urls.filter((url) => {
    let path = url;
    try {
      path = new URL(url).pathname;
    } catch {
      // Use full string if not valid URL
    }

    if (excludePatterns.length > 0) {
      const excluded = excludePatterns.some(
        (pat) => matchesGlob(path, pat) || matchesGlob(url, pat)
      );
      if (excluded) return false;
    }

    if (includePatterns.length > 0) {
      const included = includePatterns.some(
        (pat) => matchesGlob(path, pat) || matchesGlob(url, pat)
      );
      if (!included) return false;
    }

    return true;
  });
}

function downloadSchemaAsJson(schema: ExtractionSchema, filename = "extraction-schema.json"): void {
  const jsonStr = JSON.stringify(schema, null, 2);
  const blob = new Blob([jsonStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

function parseSchemaFromJson(
  jsonStr: string
): { success: true; schema: ExtractionSchema } | { success: false; error: string } {
  try {
    const raw = JSON.parse(jsonStr);
    const parsed = extractionSchemaZod.safeParse(raw);
    if (!parsed.success) {
      return {
        success: false,
        error: parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join(", "),
      };
    }
    return { success: true, schema: parsed.data as ExtractionSchema };
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    return { success: false, error: `Invalid JSON format: ${msg}` };
  }
}

