def validate_bucket_name(cls, v: str) -> str:
        name = v.strip()
        # S3 bucket naming rules: 3-63 chars, lowercase letters, numbers, dots, hyphens.
        # Starts and ends with a letter or number.
        pattern = r"^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$"
