                )
            return SandboxHealthStatus(
                status="degraded",
                server_connected=False,
                server_url=server_url,
                active_sessions_count=len(self._active_sessions),
                error=f"Server returned status {resp.status_code}",
            )
        except Exception as exc:
            return SandboxHealthStatus(
