async def stream_zip(
        self, bucket: str, slug: str, chunk_size: int = 65536
    ) -> AsyncIterator[bytes]:
        prefix = f"{slug}/"
        keys = await storage_service.list_keys(bucket, prefix)
        if not keys:
            raise ProjectNotFoundError(f"Project '{slug}' not found or empty.")

        spooled = tempfile.SpooledTemporaryFile(max_size=32 * 1024 * 1024)

        def _build_zip():
            with zipfile.ZipFile(spooled, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
                client = storage_service._get_sync_client()
                for key in keys:
                    rel_name = key[len(prefix) :]
                    if not rel_name:
                        continue
                    try:
                        res = client.get_object(Bucket=bucket, Key=key)
                        data = res["Body"].read()
                        zf.writestr(rel_name, data)
                    except Exception as exc:
                        logger.warning("Failed to include %s in zip: %s", key, exc)

        await asyncio.to_thread(_build_zip)
        spooled.seek(0)

        while True:
            chunk = await asyncio.to_thread(spooled.read, chunk_size)
            if not chunk:
                break
            yield chunk

        spooled.close()

async def check_health(self) -> StorageHealthStatus:
        start_time = time.perf_counter()
        health_url = f"{self.endpoint_url}/health"

        try:
            async with httpx.AsyncClient(timeout=httpx.Timeout(2.0, connect=1.0)) as http_client:
                res = await http_client.get(health_url)
                latency_ms = (time.perf_counter() - start_time) * 1000.0
                if res.is_success:
                    return StorageHealthStatus(
                        status="healthy",
                        service_url=self.endpoint_url,
                        latency_ms=round(latency_ms, 2),
                    )
        except Exception:
            pass

        # Fallback to S3 list_buckets probe
        try:
            client = self._get_sync_client()
            await asyncio.to_thread(client.list_buckets)
            latency_ms = (time.perf_counter() - start_time) * 1000.0
            return StorageHealthStatus(
                status="healthy",
                service_url=self.endpoint_url,
                latency_ms=round(latency_ms, 2),
            )
        except Exception as exc:
            latency_ms = (time.perf_counter() - start_time) * 1000.0
            return StorageHealthStatus(
                status="unhealthy",
                service_url=self.endpoint_url,
                latency_ms=round(latency_ms, 2),
                error=str(exc),
            )

